example_queries:
# Organisations and their OpenAIRE ids
PREFIX oaire: <https://w3id.org/rete/openaire#>
SELECT ?org ?name ?id WHERE {
  ?org a oaire:Organization ; oaire:legalName ?name ; oaire:openaireId ?id .
} LIMIT 20

# Organisations per country
PREFIX oaire: <https://w3id.org/rete/openaire#>
SELECT ?country (COUNT(?org) AS ?organisations) WHERE {
  ?org oaire:countryCode ?country .
} GROUP BY ?country ORDER BY DESC(?organisations) LIMIT 20

# Organisations and their websites
PREFIX oaire: <https://w3id.org/rete/openaire#>
SELECT ?org ?name ?website WHERE {
  ?org oaire:legalName ?name ; oaire:website ?website .
} LIMIT 20

# Short names next to legal names
PREFIX oaire: <https://w3id.org/rete/openaire#>
SELECT ?short ?name WHERE {
  ?org oaire:legalShortName ?short ; oaire:legalName ?name .
} LIMIT 20

# Swiss organisations
PREFIX oaire: <https://w3id.org/rete/openaire#>
SELECT ?org ?name WHERE {
  ?org oaire:countryCode "CH" ; oaire:legalName ?name .
} LIMIT 20
